const leerSel = (k) => {
  let v = '';
  try { v = $memory.get(k, ''); } catch (e) { try { v = $memory.getJson(k, {}); } catch (e2) { v = ''; } }
  return v;
};
const selA = leerSel('agencia_sel');
const idAg = String(typeof selA === 'object' && selA ? (selA.id || '') : selA);
const filasAg = $memory.getJson('agencias_ciudad', []) || [];
const ag = filasAg.find((a) => String(a.id) === idAg) || {};
$memory.set('id_agencia_elegida', idAg);
$memory.set('agencia_elegida', String(ag.nombre || ''));
// D-14/D-15: notas con marca, modelos, agencia, ciudad y origen; sin forma de pago ni entrada.
const limpio = (s) => String(s || '').replace(/["\\\r\n\t]/g, ' ').replace(/\s+/g, ' ').trim();
let nombres = '';
try { nombres = limpio($user.get('names') || ''); } catch (e) { nombres = ''; }
const origen = ['origen_plataforma', 'origen_campana', 'origen_anuncio']
  .map((k) => limpio($memory.get(k, ''))).filter(Boolean).join(' / ');
const notas = [
  `Marca: ${limpio($memory.get('marca_nombre_ventas', ''))}`,
  `Modelo: ${limpio($memory.get('modelo_nombre', ''))}`,
  `Modelos consultados: ${limpio($memory.get('modelos_consultados', ''))}`,
  `Agencia: ${limpio($memory.get('agencia_elegida', ''))}`,
  `Ciudad: ${limpio($memory.get('ciudad_elegida', ''))}`,
  origen ? `Origen: ${origen}` : 'Origen: directo',
  'Canal: WhatsApp',
].join('. ').slice(0, 1000);
$memory.set('lead_nombres', nombres.slice(0, 120));
$memory.setJson('lead_notas', { value: notas }, 86400);
$memory.set('lead_ciudad', limpio($memory.get('ciudad_elegida', '')).slice(0, 100));

const r = $memory.getJson('ventasResult', {});
let accion = String(r.accion || '').toLowerCase();
if (!['cotizar', 'asesor', 'sin_interes'].includes(accion)) accion = 'asesor';
if (r.id_marca) $memory.set('id_marca_ventas', String(r.id_marca));
if (r.marca_nombre) $memory.set('marca_nombre_ventas', String(r.marca_nombre));
$memory.set('id_modelo', String(r.id_modelo || ''));
$memory.set('modelo_nombre', String(r.modelo_nombre || ''));
$memory.set('modelos_consultados', String(r.modelos_consultados || r.modelo_nombre || ''));
$memory.set('accion_ventas', accion);
$memory.set('motivo_derivacion', accion === 'cotizar' ? 'cotizacion' : String(r.motivo || 'asesor'));

// RN-06: 10 dígitos; 1 reintento y al segundo error, asesor.
const ced = String($memory.get('cedula_ingresada', '') || '').replace(/\D/g, '');
const intentos = Number($memory.get('cedula_intentos', '0') || 0) + 1;
$memory.set('cedula_intentos', String(intentos));
if (/^\d{10}$/.test(ced)) {
  $memory.set('cedula', ced);
  $memory.set('cedula_ok', 'si');
} else {
  $memory.set('cedula_ok', 'no');
  if (intentos >= 2) {
    $memory.set('motivo_derivacion', 'cedula_invalida');
    $memory.set('mensaje_cierre', 'No pudimos validar su cédula. Un asesor continuará con usted por este chat.');
  }
}

const todas = $memory.getJson('ciudades_todas', []) || [];
const paginas = Math.max(1, Math.ceil(todas.length / 9));
const pag = (Number($memory.get('ciudades_pag', '0') || 0) + 1) % paginas;
$memory.set('ciudades_pag', String(pag));
$memory.setJson('ciudades_pagina', todas.slice(pag * 9, pag * 9 + 9), 86400);

// Una variable vacía pasada por un nodo MEMORY llega como ": null,": se limpia aquí.
function limpio(k) {
  const v = String($memory.get(k, "") || "").trim();
  return /^:?\s*null,?$/i.test(v) || v === "undefined" ? "" : v;
}
const marca = (limpio("marca_activa") || limpio("marca_seleccionada")).replace(/\D/g, "");
$memory.set("id_marca_ventas", marca);
$memory.set("marca_nombre_ventas", marca ? limpio("marca_nombre") : "");
$memory.set("modelos_consultados", limpio("modelos_consultados"));
$memory.set("mensaje_inicial", limpio("mensaje_inicial"));
$memory.set("consulta_vehiculo", limpio("consulta_vehiculo"));

// HU-06 c4: solo las agencias de la marca en la ciudad elegida (máx. 10 filas de WhatsApp).
const corto = (s, n) => (s.length > n ? s.slice(0, n - 1) + '…' : s);
const norm = (s) => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
const leerSel = (k) => {
  let v = '';
  try { v = $memory.get(k, ''); } catch (e) { try { v = $memory.getJson(k, {}); } catch (e2) { v = ''; } }
  return v;
};
const sel = leerSel('ciudad_sel');
const ciudadValor = String(typeof sel === 'object' && sel ? (sel.valor || sel.nombre || '') : sel);
$memory.set('ciudad_elegida', ciudadValor);
const ciudad = norm(ciudadValor);
const todas = $memory.getJson('agencias_marca', []) || [];
const filas = todas.filter((a) => norm(a.ciudad) === ciudad).slice(0, 10).map((a) => ({
  id: a.id, nombre: a.nombre, titulo: corto(a.nombre, 24), detalle: corto(a.direccion, 72) }));
$memory.setJson('agencias_ciudad', filas, 86400);
$memory.set('ciudad_nombre', ($memory.get('ciudad_elegida', '') || '').toLowerCase().replace(/(^|\s)\S/g, (c) => c.toUpperCase()));

// RF-006 / HU-06 c3: ciudades de la marca; más de 10 se pagina de 9 en 9 con «Ver más».
const corto = (s, n) => (s.length > n ? s.slice(0, n - 1) + '…' : s);
const titulo = (s) => s.toLowerCase().replace(/(^|\s)\S/g, (c) => c.toUpperCase());
let agencias = [];
try {
  const j = $context.getHttpResponse('agenciasResp').json();
  if (j.tipo === 'ok' && j.data && Array.isArray(j.data.agencias)) agencias = j.data.agencias;
} catch (e) { agencias = []; }
const ciudades = [...new Set(agencias.map((a) => String(a.ciudad || '').trim()).filter(Boolean))].sort()
  .map((c) => ({ nombre: corto(titulo(c), 24), valor: c }));
if (!ciudades.length) {
  $memory.set('hay_ciudades', 'no');
  $memory.set('motivo_derivacion', 'api_agencias');
  $memory.set('mensaje_cierre', 'En este momento no puedo consultar las agencias. Un asesor continuará con usted por este chat.');
} else {
  $memory.set('hay_ciudades', 'si');
  $memory.setJson('agencias_marca', agencias.map((a) => ({
    id: String(a.id), nombre: String(a.nombre || ''), ciudad: String(a.ciudad || ''),
    direccion: String(a.direccion || ''), horario: String(a.horario || '') })), 86400);
  $memory.setJson('ciudades_todas', ciudades, 86400);
  const paginar = ciudades.length > 10;
  $memory.set('ciudades_pag', '0');
  $memory.setJson('ciudades_pagina', paginar ? ciudades.slice(0, 9) : ciudades, 86400);
  $memory.set('ciudades_hay_mas', paginar ? 'si' : 'no');
}

// HU-06 c6-c8, resultado incierto y D-37. Nunca se pide al usuario que lo reintente.
let j = null;
try { j = $context.getHttpResponse('leadResp').json(); } catch (e) { j = null; }
const tipo = j && j.tipo ? String(j.tipo) : 'incierto';
const data = (j && j.data) || {};
const a = data.asesor || null;
const agencia = $memory.get('agencia_elegida', '');
let estado = 'derivado';
let msg = 'Un asesor continuará con usted por este chat.';
if (tipo === 'ok') {
  estado = 'registrado';
  msg = a && a.nombre
    ? `Listo. Le atenderá ${a.nombre} de la agencia ${a.agencia || agencia}. En breve continuará con usted por este chat.`
    : `Listo. Registramos su solicitud de cotización. Un asesor de la agencia ${agencia} continuará con usted por este chat.`;
} else if (tipo === 'incierto' || tipo === 'indisponible') {
  estado = 'incierto';
  msg = 'Estamos confirmando su registro; un asesor continuará con usted por este chat.';
}
$memory.set('motivo_derivacion', data.motivo === 'listas_negras' ? 'lead_listas_negras' : (tipo === 'ok' ? 'cotizacion' : 'lead_' + tipo));
$memory.set('asesor_nombre', a ? String(a.nombre || '') : '');
$memory.set('asesor_correo', a ? String(a.correo || '') : '');
$memory.set('id_prospecto', String(data.id_prospecto || ''));
$memory.set('lead_estado', estado);
$memory.set('lead_fecha', new Date().toISOString());
$memory.set('clave_lead', `${String($memory.get('celular', '')).replace(/\D/g, '')}-${$memory.get('id_marca_ventas', '')}`);
$memory.set('mensaje_cierre', msg);
if (tipo === 'ok' || tipo === 'incierto') {
  const previos = $memory.getJson('leads_registrados', {}) || {};
  previos[String($memory.get('id_marca_ventas', ''))] = { asesor: a ? a.nombre : '', correo: a ? a.correo : '', agencia: a ? (a.agencia || agencia) : agencia };
  $memory.setJson('leads_registrados', previos, 86400);
}

// T009: un lead por marca y conversación (RF-008); el celular lo asegura Bienvenida.
const marca = String($memory.get('id_marca_ventas', '') || '').replace(/\D/g, '');
const cel = String($memory.get('celular', '') || '').replace(/\D/g, '');
const celOk = /^09\d{8}$/.test(cel) || /^5939\d{8}$/.test(cel);
const previos = $memory.getJson('leads_registrados', {}) || {};
$memory.set('cedula_intentos', '0');
$memory.set('motivo_derivacion', 'cotizacion');
let estado = 'nuevo';
if (!celOk) {
  estado = 'cerrar';
  $memory.set('motivo_derivacion', 'sin_celular');
  $memory.set('mensaje_cierre', 'Para continuar con su cotización, un asesor continuará con usted por este chat.');
} else if (previos[marca]) {
  const p = previos[marca];
  estado = 'cerrar';
  $memory.set('asesor_nombre', String(p.asesor || ''));
  $memory.set('asesor_correo', String(p.correo || ''));
  $memory.set('agencia_elegida', String(p.agencia || ''));
  $memory.set('mensaje_cierre', p.asesor
    ? `Su cotización ya está registrada. Le atenderá ${p.asesor} de la agencia ${p.agencia}. En breve continuará con usted por este chat.`
    : 'Su cotización ya está registrada. Un asesor continuará con usted por este chat.');
}
if (estado === 'nuevo' && !String($memory.get('id_modelo', '') || '').trim()) {
  // Cotizar sin modelo elegido: sigue la derivación de siempre (motivo cotizacion).
  estado = 'sin_modelo';
}
$memory.set('cot_estado', estado);

// D-38: con asesor en la marca no se registra lead (HU-06 criterio 9). Si 4.5 falla, se sigue.
let tiene = 'no';
try {
  const j = $context.getHttpResponse('asesorCotResp').json();
  if (j.tipo === 'ok' && j.data && j.data.nombre) {
    tiene = 'si';
    $memory.set('asesor_nombre', String(j.data.nombre || ''));
    $memory.set('asesor_correo', String(j.data.correo || ''));
    $memory.set('agencia_elegida', String(j.data.agencia || ''));
    $memory.set('lead_estado', 'asesor_existente');
    $memory.set('mensaje_cierre', `Usted ya tiene un asesor asignado en ${$memory.get('marca_nombre_ventas', '') || 'esta marca'}: le atenderá ${j.data.nombre} de la agencia ${j.data.agencia}. En breve continuará con usted por este chat.`);
  }
} catch (e) { tiene = 'no'; }
$memory.set('cot_tiene_asesor', tiene);
